"""==============================================================================IOTEC112_CONTROL_TOWER_ENGINE.py==============================================================================Central de Operações IOTEC=============================================================================="""from __future__ import annotationsimport sqlite3import tkinter as tkfrom tkinter import ttkfrom pathlib import PathDATABASE = Path("iotec.db")# =============================================================================class ControlTower:    def __init__(self):        self.conn = sqlite3.connect(DATABASE)        self.conn.row_factory = sqlite3.Row        self.root = tk.Tk()        self.root.title("IOTEC • CONTROL TOWER")        self.root.geometry("1200x700")        self.root.configure(bg="#101820")        self.build_layout()        self.update_dashboard()        self.root.mainloop()    # =========================================================================    def build_layout(self):        style = ttk.Style()        style.theme_use("clam")        title = tk.Label(            self.root,            text="IOTEC CONTROL TOWER",            font=("Segoe UI", 20, "bold"),            fg="white",            bg="#101820"        )        title.pack(pady=10)        # ---------------------------------------------------------------------        cards = tk.Frame(            self.root,            bg="#101820"        )        cards.pack(fill="x", padx=15)        self.lbl_agents = self.card(cards, "AGENTES")        self.lbl_online = self.card(cards, "ONLINE")        self.lbl_missions = self.card(cards, "MISSÕES")        self.lbl_events = self.card(cards, "EVENTOS")        self.lbl_memory = self.card(cards, "MEMÓRIA")        # ---------------------------------------------------------------------        center = tk.Frame(            self.root,            bg="#101820"        )        center.pack(fill="both", expand=True, padx=15, pady=10)        # ---------------------------------------------------------------------        frame_left = tk.LabelFrame(            center,            text="MISSÕES",            bg="#101820",            fg="white"        )        frame_left.pack(            side="left",            fill="both",            expand=True,            padx=5        )        self.tree_missions = ttk.Treeview(            frame_left,            columns=("uuid", "status", "agent"),            show="headings",            height=18        )        self.tree_missions.heading("uuid", text="MISSÃO")        self.tree_missions.heading("status", text="STATUS")        self.tree_missions.heading("agent", text="AGENTE")        self.tree_missions.pack(fill="both", expand=True)        # ---------------------------------------------------------------------        frame_right = tk.LabelFrame(            center,            text="EVENTOS",            bg="#101820",            fg="white"        )        frame_right.pack(            side="right",            fill="both",            expand=True,            padx=5        )        self.tree_events = ttk.Treeview(            frame_right,            columns=("time", "agent", "action"),            show="headings",            height=18        )        self.tree_events.heading("time", text="HORÁRIO")        self.tree_events.heading("agent", text="AGENTE")        self.tree_events.heading("action", text="AÇÃO")        self.tree_events.pack(fill="both", expand=True)    # =========================================================================    def card(self, parent, title):        frame = tk.Frame(            parent,            bg="#1E2A38",            width=180,            height=80        )        frame.pack(            side="left",            padx=6,            pady=5,            fill="x",            expand=True        )        tk.Label(            frame,            text=title,            bg="#1E2A38",            fg="white",            font=("Segoe UI", 10, "bold")        ).pack(pady=(10, 2))        value = tk.Label(            frame,            text="0",            bg="#1E2A38",            fg="#00FF99",            font=("Segoe UI", 18, "bold")        )        value.pack()        return value    # =========================================================================    def count(self, sql):        return self.conn.execute(sql).fetchone()[0]    # =========================================================================    def load_cards(self):        self.lbl_agents.config(            text=self.count("SELECT COUNT(*) FROM agent_registry")        )        self.lbl_online.config(            text=self.count(                "SELECT COUNT(*) FROM agent_registry WHERE status='ONLINE'"            )        )        self.lbl_missions.config(            text=self.count(                "SELECT COUNT(*) FROM missions"            )        )        self.lbl_events.config(            text=self.count(                "SELECT COUNT(*) FROM agent_governance"            )        )        self.lbl_memory.config(            text=self.count(                "SELECT COUNT(*) FROM agent_memory"            )        )    # =========================================================================    def load_missions(self):        for row in self.tree_missions.get_children():            self.tree_missions.delete(row)        rows = self.conn.execute("""            SELECT                mission_uuid,                status,                assigned_agent            FROM missions            ORDER BY id DESC            LIMIT 50        """).fetchall()        for r in rows:            self.tree_missions.insert(                "",                "end",                values=(                    r["mission_uuid"],                    r["status"],                    r["assigned_agent"]                )            )    # =========================================================================    def load_events(self):        for row in self.tree_events.get_children():            self.tree_events.delete(row)        rows = self.conn.execute("""            SELECT                created_at,                agent_uuid,                action            FROM agent_governance            ORDER BY id DESC            LIMIT 50        """).fetchall()        for r in rows:            self.tree_events.insert(                "",                "end",                values=(                    r["created_at"][:19],                    r["agent_uuid"],                    r["action"]                )            )    # =========================================================================    def update_dashboard(self):        self.load_cards()        self.load_missions()        self.load_events()        self.root.after(            2000,            self.update_dashboard        )# =============================================================================if __name__ == "__main__":    ControlTower()